//! gb-core：DMG（初代 Game Boy）模拟器核心，零依赖。
//!
//! 时钟模型（DECISIONS D002）：CPU 驱动时钟，每次总线访问或内部周期 = 1 个 M-cycle；
//! 每个 M-cycle 内 Bus 先把所有外设推进 4 T，再执行访问。
//!
//! 本文件归 integrator 所有（PLAN §6.4）；跨通道接口在 T02 冻结（DECISIONS D001），
//! 改动签名前必须先记 DECISIONS.md。

pub mod alu;
pub mod bus;
pub mod cart;
pub mod cpu;
pub mod decode;
pub mod dma;
pub mod interrupts;
pub mod joypad;
pub mod machine;
pub mod ppu;
pub mod serial;
pub mod state;
pub mod timer;

pub use cart::{Cart, CartError};
pub use cpu::{Cpu, CpuBus};
pub use machine::{Machine, Regs};
pub use state::{Snapshot, StateError, StateReader, StateWriter};

/// 屏幕宽度（像素）。
pub const SCREEN_W: usize = 160;
/// 屏幕高度（像素）。
pub const SCREEN_H: usize = 144;
/// 一帧的像素数；帧缓冲每字节一个像素，取值只有 0xFF/0xAA/0x55/0x00（色号 0 = 0xFF）。
pub const FRAME_PIXELS: usize = SCREEN_W * SCREEN_H;
/// 一帧的 T-cycle 数（154 行 × 456 dot）。`Machine::run_frame` 与 LCD 开关无关地按它推进。
pub const FRAME_T: u32 = 70224;

/// 一帧画面：160×144，行优先。
pub type Frame = [u8; FRAME_PIXELS];

/// 中断位（IF/IE 的 bit 序号与掩码）。`CpuBus::ack` 接收的是 bit 序号 0..=4。
pub mod irq {
    pub const VBLANK: u8 = 1 << 0;
    pub const STAT: u8 = 1 << 1;
    pub const TIMER: u8 = 1 << 2;
    pub const SERIAL: u8 = 1 << 3;
    pub const JOYPAD: u8 = 1 << 4;
}

/// `Machine::set_buttons` 的位定义：1 = 按下。
pub mod buttons {
    pub const A: u8 = 1 << 0;
    pub const B: u8 = 1 << 1;
    pub const SELECT: u8 = 1 << 2;
    pub const START: u8 = 1 << 3;
    pub const RIGHT: u8 = 1 << 4;
    pub const LEFT: u8 = 1 << 5;
    pub const UP: u8 = 1 << 6;
    pub const DOWN: u8 = 1 << 7;
}

/// 外设统一形态（timer/serial/joypad/ppu 都遵守；DMA 另有接口，见 `dma.rs`）。
///
/// Bus 每个 M-cycle 依次调用 timer → serial → joypad → ppu 的 `tick_mcycle`，再推进 DMA，
/// 并把返回的中断位或进 IF。`read_reg` 必须无副作用（`Machine::peek` 也走它）。
pub trait Peripheral: Snapshot {
    /// 推进 1 个 M-cycle（4 T），返回本周期新请求的中断位（IF 位掩码，见 `irq`）。
    fn tick_mcycle(&mut self) -> u8;
    /// 读 I/O 寄存器，`addr` 为绝对地址（如 0xFF04）。
    fn read_reg(&self, addr: u16) -> u8;
    /// 写 I/O 寄存器，`addr` 为绝对地址。
    fn write_reg(&mut self, addr: u16, v: u8);
}
//! PPU（ppu 通道，T40–T42）：逐扫描线渲染加双缓冲（PLAN §3.5）。
//!
//! 冻结部分（D001）：`Ppu::new`、VRAM/OAM 访问方法、`dma_write_oam`、`frame`、`Peripheral` 实现
//! （`tick_mcycle` 返回 VBlank/STAT 中断位；`read_reg`/`write_reg` 处理 FF40–FF45、FF47–FF4B；
//! FF46 归 `dma.rs`）、`Snapshot`。VRAM 与 OAM 数组由本模块持有，Bus 只做转发。
//!
//! T02 空壳：存储与访问已可用，`tick_mcycle` 不推进时序（返回 0），由 T40 替换。
//! 在此之前整机仍可运行（Blargg 的控制台在 LY 不变时会超时后继续）。

use crate::state::{Snapshot, StateError, StateReader, StateWriter};
use crate::{Frame, Peripheral, FRAME_PIXELS};

pub struct Ppu {
    vram: [u8; 0x2000],
    oam: [u8; 0xA0],
    /// 最近一个完整帧（进入 LY=144 时由后缓冲交换而来）。
    front: Box<Frame>,
    /// 正在绘制的帧。
    back: Box<Frame>,
    /// FF40–FF4B 的寄存器存储（T02 空壳用；T40 起可替换为具名字段）。
    regs: [u8; 12],
}

impl Default for Ppu {
    fn default() -> Self {
        Self::new()
    }
}

impl Ppu {
    /// DMG 开机状态（Pan Docs Power_Up_Sequence 的硬件寄存器表，DMG 列），前缓冲为全白。
    pub fn new() -> Self {
        let mut regs = [0u8; 12];
        regs[0x0] = 0x91; // LCDC
        regs[0x1] = 0x85; // STAT
        regs[0x7] = 0xFC; // BGP
        Self {
            vram: [0; 0x2000],
            oam: [0; 0xA0],
            front: Box::new([0xFF; FRAME_PIXELS]),
            back: Box::new([0xFF; FRAME_PIXELS]),
            regs,
        }
    }

    /// CPU 读 VRAM，`addr` 为绝对地址 0x8000..=0x9FFF。无副作用（`peek` 也走这里）。
    pub fn read_vram(&self, addr: u16) -> u8 {
        self.vram[(addr & 0x1FFF) as usize]
    }

    /// CPU 写 VRAM，`addr` 为绝对地址 0x8000..=0x9FFF。
    pub fn write_vram(&mut self, addr: u16, v: u8) {
        self.vram[(addr & 0x1FFF) as usize] = v;
    }

    /// CPU 读 OAM，`addr` 为绝对地址 0xFE00..=0xFE9F。无副作用。
    pub fn read_oam(&self, addr: u16) -> u8 {
        self.oam[(addr as usize - 0xFE00) % 0xA0]
    }

    /// CPU 写 OAM，`addr` 为绝对地址 0xFE00..=0xFE9F。
    pub fn write_oam(&mut self, addr: u16, v: u8) {
        self.oam[(addr as usize - 0xFE00) % 0xA0] = v;
    }

    /// OAM DMA 写入第 `index`（0..160）个字节；由 Bus 驱动，不受 PPU 模式封锁影响。
    pub fn dma_write_oam(&mut self, index: u8, v: u8) {
        self.oam[index as usize % 0xA0] = v;
    }

    /// 最近一个完整帧（前缓冲），值为 0xFF/0xAA/0x55/0x00。
    pub fn frame(&self) -> &Frame {
        &self.front
    }
}

impl Peripheral for Ppu {
    fn tick_mcycle(&mut self) -> u8 {
        // T02 空壳：T40 实现 dot 计数、LY、mode、STAT、VBlank 与双缓冲交换。
        let _ = &mut self.back;
        0
    }

    fn read_reg(&self, addr: u16) -> u8 {
        match addr {
            0xFF40..=0xFF4B => self.regs[(addr - 0xFF40) as usize],
            _ => 0xFF,
        }
    }

    fn write_reg(&mut self, addr: u16, v: u8) {
        if let 0xFF40..=0xFF4B = addr {
            self.regs[(addr - 0xFF40) as usize] = v;
        }
    }
}

impl Snapshot for Ppu {
    fn save(&self, _w: &mut StateWriter) {
        todo!("ppu: Snapshot for Ppu")
    }
    fn load(&mut self, _r: &mut StateReader) -> Result<(), StateError> {
        todo!("ppu: Snapshot for Ppu")
    }
}
//! OAM DMA 状态（ppu 通道，T42）。实际搬运由 Bus 驱动（PLAN §3.2）：
//! Bus 每个 M-cycle 调用一次 `tick_mcycle`，返回 `Some((src, index))` 时从总线读 `src`
//! （不推进时钟、无副作用），再调用 `Ppu::dma_write_oam(index, v)`。
//!
//! 冻结部分（D001）：下列公开方法的签名。

use crate::state::{Snapshot, StateError, StateReader, StateWriter};

#[derive(Debug, Clone, Default)]
pub struct Dma {
    /// 最近一次写入 FF46 的值（读 FF46 返回它）。
    reg: u8,
}

impl Dma {
    pub fn new() -> Self {
        Self { reg: 0xFF }
    }

    /// 读 FF46。
    pub fn read_reg(&self) -> u8 {
        self.reg
    }

    /// 写 FF46：启动（或重启）一次 160 字节的传输，源地址为 `v << 8`。
    pub fn write_reg(&mut self, v: u8) {
        // T02 空壳：T42 实现启动延迟、进度与重启。
        self.reg = v;
    }

    /// 推进 1 个 M-cycle；本周期需要搬运一个字节时返回 `Some((源地址, OAM 序号 0..160))`。
    pub fn tick_mcycle(&mut self) -> Option<(u16, u8)> {
        None
    }

    /// 传输进行中（CPU 访问 OAM 读到 0xFF、写入被忽略）。
    pub fn oam_blocked(&self) -> bool {
        false
    }
}

impl Snapshot for Dma {
    fn save(&self, _w: &mut StateWriter) {
        todo!("ppu: Snapshot for Dma")
    }
    fn load(&mut self, _r: &mut StateReader) -> Result<(), StateError> {
        todo!("ppu: Snapshot for Dma")
    }
}
//! 存档的小端字节读写与 `Snapshot` trait（T02 冻结并完整实现）。
//!
//! 每个模块的所有者随模块实现 `Snapshot`：`save` 按固定顺序写字段，`load` 按同样顺序读回。
//! 建议每个模块以 `w.tag(b"XXXX")` / `r.tag(b"XXXX")?` 开头，错位时能立即定位到模块。

use std::fmt;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum StateError {
    /// 数据提前结束。
    Truncated,
    /// 文件头 magic 不是 `GBEMUST`。
    BadMagic,
    /// 存档版本与当前实现不符。
    BadVersion(u16),
    /// ROM 指纹（头部校验和、全局校验和、标题）与当前卡带不符。
    RomMismatch,
    /// 模块标签不符或字段取值非法；参数说明位置。
    Corrupt(&'static str),
}

impl fmt::Display for StateError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            StateError::Truncated => write!(f, "save state truncated"),
            StateError::BadMagic => write!(f, "not a gbemu save state"),
            StateError::BadVersion(v) => write!(f, "unsupported save state version {v}"),
            StateError::RomMismatch => write!(f, "save state belongs to a different ROM"),
            StateError::Corrupt(what) => write!(f, "corrupt save state: {what}"),
        }
    }
}

impl std::error::Error for StateError {}

pub trait Snapshot {
    fn save(&self, w: &mut StateWriter);
    fn load(&mut self, r: &mut StateReader) -> Result<(), StateError>;
}

#[derive(Debug, Default)]
pub struct StateWriter {
    buf: Vec<u8>,
}

impl StateWriter {
    pub fn new() -> Self {
        Self { buf: Vec::new() }
    }
    pub fn into_inner(self) -> Vec<u8> {
        self.buf
    }
    pub fn len(&self) -> usize {
        self.buf.len()
    }
    pub fn is_empty(&self) -> bool {
        self.buf.is_empty()
    }
    /// 4 字节模块标签，用于检测错位。
    pub fn tag(&mut self, t: &[u8; 4]) {
        self.buf.extend_from_slice(t);
    }
    pub fn u8(&mut self, v: u8) {
        self.buf.push(v);
    }
    pub fn bool(&mut self, v: bool) {
        self.buf.push(v as u8);
    }
    pub fn u16(&mut self, v: u16) {
        self.buf.extend_from_slice(&v.to_le_bytes());
    }
    pub fn u32(&mut self, v: u32) {
        self.buf.extend_from_slice(&v.to_le_bytes());
    }
    pub fn u64(&mut self, v: u64) {
        self.buf.extend_from_slice(&v.to_le_bytes());
    }
    pub fn i64(&mut self, v: i64) {
        self.buf.extend_from_slice(&v.to_le_bytes());
    }
    /// 定长字节（读回时用 `StateReader::bytes_into`，长度由调用方保证一致）。
    pub fn bytes(&mut self, v: &[u8]) {
        self.buf.extend_from_slice(v);
    }
    /// 变长字节：u32 长度前缀 + 数据（读回时用 `StateReader::vec`）。
    pub fn vec(&mut self, v: &[u8]) {
        self.u32(v.len() as u32);
        self.buf.extend_from_slice(v);
    }
}

#[derive(Debug)]
pub struct StateReader<'a> {
    data: &'a [u8],
    pos: usize,
}

impl<'a> StateReader<'a> {
    pub fn new(data: &'a [u8]) -> Self {
        Self { data, pos: 0 }
    }
    pub fn remaining(&self) -> usize {
        self.data.len() - self.pos
    }
    fn take(&mut self, n: usize) -> Result<&'a [u8], StateError> {
        if self.remaining() < n {
            return Err(StateError::Truncated);
        }
        let s = &self.data[self.pos..self.pos + n];
        self.pos += n;
        Ok(s)
    }
    pub fn tag(&mut self, t: &[u8; 4]) -> Result<(), StateError> {
        if self.take(4)? == t {
            Ok(())
        } else {
            Err(StateError::Corrupt("module tag mismatch"))
        }
    }
    pub fn u8(&mut self) -> Result<u8, StateError> {
        Ok(self.take(1)?[0])
    }
    pub fn bool(&mut self) -> Result<bool, StateError> {
        match self.u8()? {
            0 => Ok(false),
            1 => Ok(true),
            _ => Err(StateError::Corrupt("bool")),
        }
    }
    pub fn u16(&mut self) -> Result<u16, StateError> {
        Ok(u16::from_le_bytes(self.take(2)?.try_into().unwrap()))
    }
    pub fn u32(&mut self) -> Result<u32, StateError> {
        Ok(u32::from_le_bytes(self.take(4)?.try_into().unwrap()))
    }
    pub fn u64(&mut self) -> Result<u64, StateError> {
        Ok(u64::from_le_bytes(self.take(8)?.try_into().unwrap()))
    }
    pub fn i64(&mut self) -> Result<i64, StateError> {
        Ok(i64::from_le_bytes(self.take(8)?.try_into().unwrap()))
    }
    pub fn bytes_into(&mut self, out: &mut [u8]) -> Result<(), StateError> {
        out.copy_from_slice(self.take(out.len())?);
        Ok(())
    }
    pub fn vec(&mut self) -> Result<Vec<u8>, StateError> {
        let n = self.u32()? as usize;
        Ok(self.take(n)?.to_vec())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn roundtrip_all_types() {
        let mut w = StateWriter::new();
        w.tag(b"TEST");
        w.u8(0xAB);
        w.bool(true);
        w.u16(0x1234);
        w.u32(0xDEADBEEF);
        w.u64(0x0123_4567_89AB_CDEF);
        w.i64(-5);
        w.bytes(&[1, 2, 3]);
        w.vec(&[9, 8]);
        let data = w.into_inner();
        let mut r = StateReader::new(&data);
        r.tag(b"TEST").unwrap();
        assert_eq!(r.u8().unwrap(), 0xAB);
        assert!(r.bool().unwrap());
        assert_eq!(r.u16().unwrap(), 0x1234);
        assert_eq!(r.u32().unwrap(), 0xDEADBEEF);
        assert_eq!(r.u64().unwrap(), 0x0123_4567_89AB_CDEF);
        assert_eq!(r.i64().unwrap(), -5);
        let mut three = [0u8; 3];
        r.bytes_into(&mut three).unwrap();
        assert_eq!(three, [1, 2, 3]);
        assert_eq!(r.vec().unwrap(), vec![9, 8]);
        assert_eq!(r.remaining(), 0);
        assert_eq!(r.u8(), Err(StateError::Truncated));
    }

    #[test]
    fn tag_mismatch_is_error() {
        let mut w = StateWriter::new();
        w.tag(b"AAAA");
        let data = w.into_inner();
        assert!(StateReader::new(&data).tag(b"BBBB").is_err());
    }
}
[package]
name = "gb-core"
description = "DMG (original Game Boy) emulator core, zero dependencies"
version.workspace = true
edition.workspace = true
license.workspace = true

[lib]
name = "gb_core"
path = "src/lib.rs"

