//! OAM DMA 状态（ppu 通道，T42）。实际搬运由 Bus 驱动（PLAN §3.2）：
//! Bus 每个 M-cycle 调用一次 `tick_mcycle`，返回 `Some((src, index))` 时从总线读 `src`
//! （不推进时钟、无副作用），再调用 `Ppu::dma_write_oam(index, v)`。
//!
//! 冻结部分（D001）：下列公开方法的签名。
//!
//! # 时序（`OAM_DMA_Transfer.md`；Mooneye `oam_dma_start`、`oam_dma_timing`、`oam_dma_restart`）
//!
//! 以写 FF46 的 M-cycle 为 M=0（Bus 先 tick 后访问，所以写入发生在 M=0 的 tick 之后）：
//! - M=1：启动延迟，什么也不搬（若之前的传输仍在进行，它照常再搬 1 个字节）；
//! - M=2..=161：每个 M-cycle 搬 1 个字节，序号 0..=159，期间 `oam_blocked()` 为真；
//! - M=162：传输结束，OAM 恢复可访问。
//!
//! 传输进行中再次写 FF46 会重启：旧传输在 M=1 继续，新传输从 M=2 的第 0 个字节开始。
//! 源地址 0xE000 以上的映射（DMG 上读到 WRAM）由 Bus 的 `dma_source` 负责。

use crate::state::{Snapshot, StateError, StateReader, StateWriter};

/// 一次传输的字节数。
const LEN: u8 = 0xA0;
/// 写 FF46 到搬运第一个字节之间的 M-cycle 数（含写入后的第 1 个 M-cycle）。
const START_DELAY: u8 = 2;

#[derive(Debug, Clone)]
pub struct Dma {
    /// 最近一次写入 FF46 的值（读 FF46 返回它）。
    reg: u8,
    /// 正在进行的传输的源地址起点。
    src: u16,
    /// 下一个要搬的字节序号；`LEN` 表示没有传输在进行。
    index: u8,
    /// 新传输开始前剩余的 M-cycle 数（0 = 没有待启动的传输）。
    delay: u8,
    /// 待启动传输的源地址起点。
    pending_src: u16,
    /// 本 M-cycle 搬运了字节（CPU 访问 OAM 读 0xFF、写入被忽略）。
    busy: bool,
}

impl Default for Dma {
    fn default() -> Self {
        Self::new()
    }
}

impl Dma {
    pub fn new() -> Self {
        Self {
            reg: 0xFF,
            src: 0,
            index: LEN,
            delay: 0,
            pending_src: 0,
            busy: false,
        }
    }

    /// 读 FF46。
    pub fn read_reg(&self) -> u8 {
        self.reg
    }

    /// 写 FF46：启动（或重启）一次 160 字节的传输，源地址为 `v << 8`。
    pub fn write_reg(&mut self, v: u8) {
        self.reg = v;
        self.pending_src = (v as u16) << 8;
        self.delay = START_DELAY;
    }

    /// 推进 1 个 M-cycle；本周期需要搬运一个字节时返回 `Some((源地址, OAM 序号 0..160))`。
    pub fn tick_mcycle(&mut self) -> Option<(u16, u8)> {
        if self.delay > 0 {
            self.delay -= 1;
            if self.delay == 0 {
                self.src = self.pending_src;
                self.index = 0;
            }
        }
        if self.index < LEN {
            let i = self.index;
            self.index += 1;
            self.busy = true;
            Some((self.src.wrapping_add(i as u16), i))
        } else {
            self.busy = false;
            None
        }
    }

    /// 传输进行中（CPU 访问 OAM 读到 0xFF、写入被忽略）。
    pub fn oam_blocked(&self) -> bool {
        self.busy
    }
}

impl Snapshot for Dma {
    fn save(&self, w: &mut StateWriter) {
        w.tag(b"DMA ");
        w.u8(self.reg);
        w.u16(self.src);
        w.u8(self.index);
        w.u8(self.delay);
        w.u16(self.pending_src);
        w.bool(self.busy);
    }

    fn load(&mut self, r: &mut StateReader) -> Result<(), StateError> {
        r.tag(b"DMA ")?;
        let d = Dma {
            reg: r.u8()?,
            src: r.u16()?,
            index: r.u8()?,
            delay: r.u8()?,
            pending_src: r.u16()?,
            busy: r.bool()?,
        };
        if d.index > LEN || d.delay > START_DELAY {
            return Err(StateError::Corrupt("dma progress"));
        }
        *self = d;
        Ok(())
    }
}

