        self.delay = START_DELAY;
    }

    /// 推进 1 个 M-cycle；本周期需要搬运一个字节时返回 `Some((源地址, OAM 序号 0..160))`。
    pub fn tick_mcycle(&mut self) -> Option<(u16, u8)> {
        if self.delay > 0 {
            self.delay -= 1;
            if self.delay == 0 {
                self.src = self.pending_src;
                self.index = 0;
            }
        }
        if self.index < LEN {
            let i = self.index;
            self.index += 1;
            self.busy = true;
            Some((self.src.wrapping_add(i as u16), i))
        } else {
            self.busy = false;
            None
        }
    }

    /// 传输进行中（CPU 访问 OAM 读到 0xFF、写入被忽略）。
    pub fn oam_blocked(&self) -> bool {
        self.busy
    }
}

impl Snapshot for Dma {
    fn save(&self, w: &mut StateWriter) {
        w.tag(b"DMA ");
        w.u8(self.reg);
        w.u16(self.src);
        w.u8(self.index);
        w.u8(self.delay);
        w.u16(self.pending_src);
        w.bool(self.busy);
    }

    fn load(&mut self, r: &mut StateReader) -> Result<(), StateError> {
        r.tag(b"DMA ")?;
        let d = Dma {
            reg: r.u8()?,
            src: r.u16()?,
            index: r.u8()?,
            delay: r.u8()?,
            pending_src: r.u16()?,
            busy: r.bool()?,
        };
        if d.index > LEN || d.delay > START_DELAY {
            return Err(StateError::Corrupt("dma progress"));
        }
        *self = d;
        Ok(())
    }
}

